	/**
	 * Default Constructor
	 */
    public QuarantineService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new QuarantineEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(QuarantineRepository.class) );
		this.validator		= applicationContext.getBean(QuarantineValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Quarantine
	 */
		public Quarantine createQuarantine( CreateQuarantineCommand command ) {

		Quarantine entity = new Quarantine();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setQuarantineId( command.getQuarantineId() );
            entity.setReason( command.getReason() );
            entity.setStartedAt( command.getStartedAt() );
            entity.setReleasedAt( command.getReleasedAt() );
            entity.setDisposition( command.getDisposition() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Quarantine {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateQuarantineCommand
	 * @return		Quarantine
	 */
	public Quarantine updateQuarantine( UpdateQuarantineCommand command ) {

		Quarantine entity = new Quarantine();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setQuarantineId( command.getQuarantineId() );
            entity.setReason( command.getReason() );
            entity.setStartedAt( command.getStartedAt() );
            entity.setReleasedAt( command.getReleasedAt() );
            entity.setWarehouse( command.getWarehouse() );
            entity.setItems( command.getItems() );
            entity.setLot( command.getLot() );
            entity.setSerialNumbers( command.getSerialNumbers() );
            entity.setDisposition( command.getDisposition() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Quarantine {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteQuarantineCommand
	 */
	public void delete( DeleteQuarantineCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getQuarantineId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Quarantine {0} ", id );

	}

	/**
	 * Method to retrieve the Quarantine via QuarantineFetchOneSummary
	 * @param 	summary QuarantineFetchOneSummary
	 * @return 	QuarantineFetchOneResponse
	 */
	public Quarantine getQuarantine( QuarantineFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "QuarantineFetchOneSummary arg cannot be null" );

		Quarantine entity = null;
		UUID id = summary.getQuarantineId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Quarantine using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Quarantines
	 *
	 * @return 	List<Quarantine>
	 */
    public List<Quarantine> getAllQuarantine() {
		List<Quarantine> list = projector.findAll( new FindAllQuarantineQuery() );
		return list;
	}

